insert into public.properties (id,owner_id,title,description,city,rent_cents,approved,property_type,address_line_1,address_line_2,state,zip_code,bedrooms,bathrooms,square_feet,image_url,image_alt,amenities,voice_summary) values ('10000000-0000-4000-8000-000000000001','11111111-1111-4111-8111-111111111111','Sunlit Garden Apartment','Quiet second-floor apartment featuring morning light, an updated galley kitchen, and immediate access to neighborhood walking paths.','Brookhaven',265000,true,'apartment','104 Meadow Lane','Apt 2B','CA','94025',2,1.5,920,'/properties/brookhaven-apartment.svg','Exterior view of two-story residential apartment building with garden walkways',array['laundry','pet_friendly','public_transit']::text[],'Two bedroom, one and a half bath apartment on Meadow Lane in Brookhaven for twenty-six fifty per month with laundry and nearby public transit.') on conflict (id) do nothing;
insert into public.properties (id,owner_id,title,description,city,rent_cents,approved,property_type,address_line_1,address_line_2,state,zip_code,bedrooms,bathrooms,square_feet,image_url,image_alt,amenities,voice_summary) values ('10000000-0000-4000-8000-000000000002','11111111-1111-4111-8111-111111111111','Cedar Ridge Hilltop Condo','Top-floor condominium offering scenic hillside views, assigned garage parking, and an expansive private balcony.','Brookhaven',310000,true,'condo','220 Cedar Ridge Way',null,'CA','94025',2,2,1150,'/properties/brookhaven-condo.svg','Modern hillside condominium facade with glass-railing balconies',array['parking','laundry','balcony']::text[],'Two bedroom, two bath hillside condo on Cedar Ridge Way for thirty-one hundred per month with private balcony and assigned parking.') on conflict (id) do nothing;
insert into public.properties (id,owner_id,title,description,city,rent_cents,approved,property_type,address_line_1,address_line_2,state,zip_code,bedrooms,bathrooms,square_feet,image_url,image_alt,amenities,voice_summary) values ('10000000-0000-4000-8000-000000000003','11111111-1111-4111-8111-111111111111','Brookside Village Duplex','Spacious side-by-side duplex unit with a dedicated fenced backyard, attached garage, and full basement storage.','Brookhaven',285000,true,'duplex','312 Brookside Avenue',null,'CA','94025',3,2,1380,'/properties/brookhaven-duplex.svg','Front elevation of side-by-side duplex with private driveways and manicured lawns',array['yard','parking','pet_friendly']::text[],'Three bedroom, two bath duplex on Brookside Avenue for twenty-eight fifty per month with yard and attached garage.') on conflict (id) do nothing;
insert into public.properties (id,owner_id,title,description,city,rent_cents,approved,property_type,address_line_1,address_line_2,state,zip_code,bedrooms,bathrooms,square_feet,image_url,image_alt,amenities,voice_summary) values ('10000000-0000-4000-8000-000000000004','11111111-1111-4111-8111-111111111111','Whispering Pines Family House','Detached single-family home situated on a quiet cul-de-sac with mature trees, a modern kitchen island, and an expansive rear patio.','Brookhaven',420000,true,'house','418 Whispering Pines Court',null,'CA','94025',4,2.5,2200,'/properties/brookhaven-house.svg','Single-family craftsman home with covered front porch and double garage',array['yard','parking','laundry','pet_friendly']::text[],'Four bedroom, two and a half bath house on Whispering Pines Court for forty-two hundred per month with large yard and two-car garage.') on conflict (id) do nothing;
